(window.CLAVE_TEST=window.CLAVE_TEST||{})[26]=[{"a":"Artículo 14 · Derechos y deberes R2","q":[{"i":"26-210","p":"Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil. Acceso al Defensor del Pueblo. Los Guardias Civiles podrán dirigirse al Defensor del Pueblo, de acuerdo con lo previsto en la legislación reguladora del Defensor del Pueblo:","o":["A través de su asociación profesional representativa y por escrito.","Directa e individualmente.","Previa autorización del Director General de la Guardia Civil, en cada caso.","Por conducto reglamentario y a través de su jefe de unidad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Directa e individualmente</mark></span><span class=\"ref-norma\">Art. 14 · Ley Orgánica 11/2007, reguladora de los derechos y deberes de los miembros de la Guardia Civil</span> <span class=\"ref-concepto\">\"Los Guardias Civiles podrán dirigirse directa e individualmente al Defensor del Pueblo, de acuerdo con lo previsto en la legislación reguladora del Defensor del Pueblo.\"</span>"},{"i":"26-ia-1036","p":"Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil. Acceso al Defensor del Pueblo. Los Guardias Civiles podrán dirigirse directa e individualmente al Defensor del Pueblo, de acuerdo con lo previsto en:","o":["la legislación reguladora del derecho de petición, en los términos que se determinen reglamentariamente.","la legislación reguladora del Defensor del Pueblo.","esta Ley Orgánica y en su régimen disciplinario.","la Ley Orgánica de Fuerzas y Cuerpos de Seguridad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la legislación reguladora del Defensor del Pueblo</mark></span><span class=\"ref-norma\">Art.  14 · Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil</span><span class=\"ref-concepto\">\"podrán dirigirse directa e individualmente al Defensor del Pueblo, de acuerdo con lo previsto en la legislación reguladora del Defensor del Pueblo\"</span>Remite a la legislación reguladora del Defensor del Pueblo."}]},{"a":"JERARQUÍA, DISCIPLINA Y SUBORDINACIÓN pág. 13 · art. 16","q":[{"i":"26-ia-1038","p":"Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil. Jerarquía, disciplina y subordinación. Los miembros de la Guardia Civil deberán adecuar su actuación profesional a los principios de jerarquía, disciplina y subordinación. En ningún caso la obediencia debida podrá amparar el cumplimiento de órdenes que:","o":["entrañen la ejecución de actos que constituyan delito o falta grave, o sean contrarios a la Constitución o a las Leyes.","entrañen la ejecución de actos que manifiestamente constituyan delito, o sean contrarios a la Constitución, aunque no a las Leyes.","entrañen la ejecución de actos que manifiestamente constituyan infracción disciplinaria o sean contrarios a la Constitución o a las Leyes.","entrañen la ejecución de actos que manifiestamente constituyan delito o sean contrarios a la Constitución o a las Leyes."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">entrañen la ejecución de actos que manifiestamente constituyan delito o sean contrarios a la Constitución o a las Leyes</mark></span><span class=\"ref-norma\">Art.  16 · Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil</span><span class=\"ref-concepto\">\"En ningún caso la obediencia debida podrá amparar el cumplimiento de órdenes que entrañen la ejecución de actos que manifiestamente constituyan delito o sean contrarios a la Constitución o a las Leyes\"</span>La orden debe entrañar un acto que manifiestamente constituya delito o sea contrario a la Constitución o a las Leyes."}]},{"a":"CARRERA PROFESIONAL pág. 15 · art. 27","q":[{"i":"26-ia-1052","p":"Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil. Carrera profesional. Los Guardias Civiles tienen derecho al desarrollo de su carrera profesional, especialmente al régimen de ascensos, destinos, condecoraciones y recompensas, de acuerdo con los principios de:","o":["igualdad, mérito y antigüedad y de conformidad con las normas que la regulen.","igualdad, mérito, capacidad y de conformidad con las normas que la regulen.","igualdad, mérito, capacidad y disponibilidad y de conformidad con las normas que la regulen.","mérito, capacidad y antigüedad y de conformidad con las normas que la regulen."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">igualdad, mérito, capacidad y de conformidad con las normas que la regulen</mark></span><span class=\"ref-norma\">Art.  27 · Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil</span><span class=\"ref-concepto\">\"de acuerdo con los principios de igualdad, mérito, capacidad y de conformidad con las normas que la regulen\"</span>Los principios son igualdad, mérito y capacidad."}]},{"a":"PRINCIPIOS DE LA CARRERA PROFESIONAL pág. 15 · art. 27","q":[{"i":"26-19","p":"Ley Orgánica 11/2007, de 22 de octubre, Reguladora de los Derechos y Deberes de los Miembros de la Guardia Civil. Los Guardias Civiles tienen ______ al desarrollo de su carrera profesional.","o":["La obligación.","El derecho.","El deber.","B y C son correctas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El derecho</mark></span><span class=\"ref-norma\">Art. 27 · Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil</span><span class=\"ref-concepto\">\"Los Guardias Civiles tienen derecho al desarrollo de su carrera profesional\"</span>"},{"i":"26-125","p":"Ley Orgánica 11/2007, de 22 de octubre, reguladora de los Derechos y Deberes de los miembros de la Guardia Civil. De los derechos profesionales de los miembros de la guardia civil. Carrera profesional. Los Guardias Civiles tienen derecho al desarrollo de su carrera profesional, especialmente al régimen de: Señale la incorrecta.","o":["Ascensos.","Destinos.","Retribuciones.","Condecoraciones y recompensas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Retribuciones</mark></span><span class=\"ref-norma\">Art. 27 · Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil</span><span class=\"ref-concepto\">\"Los Guardias Civiles tienen derecho al desarrollo de su carrera profesional, especialmente al régimen de ascensos, destinos, condecoraciones y recompensas\"</span> Las retribuciones no figuran en la enumeración del artículo."},{"i":"26-151","p":"Ley Orgánica 11/2007, de 22 de octubre, reguladora de los Derechos y Deberes de los miembros de la Guardia Civil. Carrera profesional. Los Guardias Civiles tienen derecho al desarrollo de su carrera profesional, especialmente al régimen de ascensos, destinos, condecoraciones y recompensas, de acuerdo con los principios de:","o":["Igualdad y antigüedad.","Igualdad, mérito, capacidad.","Igualdad, mérito y antigüedad.","Igualdad, mérito y publicidad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Igualdad, mérito, capacidad</mark></span><span class=\"ref-norma\">Art. 27 · Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil</span><span class=\"ref-concepto\">\"Los Guardias Civiles tienen derecho al desarrollo de su carrera profesional, especialmente al régimen de ascensos, destinos, condecoraciones y recompensas, de acuerdo con los principios de igualdad, mérito, capacidad y de conformidad con las normas que la regulen.\"</span>"}]},{"a":"Artículo 35 · Derechos y deberes R5","q":[{"i":"26-ia-1108","p":"Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil. Retribuciones. Los miembros de la Guardia Civil tendrán derecho a una remuneración acorde con su empleo, destino y puesto de trabajo que desempeñen y que contemple su nivel de formación, régimen de incompatibilidades, movilidad por razones de servicio, dedicación y riesgo que comporta su misión, así como:","o":["especificidad de los horarios de trabajo y peculiar régimen disciplinario.","especificidad de los horarios de trabajo y peculiar estructura.","peculiaridad de los horarios de trabajo y especial estructura jerárquica.","especificidad de la jornada de trabajo y peculiar estructura orgánica."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">especificidad de los horarios de trabajo y peculiar estructura</mark></span><span class=\"ref-norma\">Art.  35 · Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil</span><span class=\"ref-concepto\">\"así como especificidad de los horarios de trabajo y peculiar estructura\"</span>Se contempla la especificidad de los horarios de trabajo y la peculiar estructura."},{"i":"26-211","p":"Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil. Retribuciones. Los miembros de la Guardia Civil tendrán derecho a una remuneración acorde con:","o":["Su empleo, destino y puesto de trabajo que desempeñen.","Su antigüedad en el Cuerpo y la escala a la que pertenezcan en todo caso.","Su empleo y destino exclusivamente, con independencia del puesto de trabajo.","Su escala y titulación académica, así como los servicios prestados en el Cuerpo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Su empleo, destino y puesto de trabajo que desempeñen</mark></span><span class=\"ref-norma\">Art. 35 · Ley Orgánica 11/2007, reguladora de los derechos y deberes de los miembros de la Guardia Civil</span> <span class=\"ref-concepto\">\"Los miembros de la Guardia Civil tendrán derecho a una remuneración acorde con su empleo, destino y puesto de trabajo que desempeñen\"</span>"}]},{"a":"RÉGIMEN ECONÓMICO DE LAS ASOCIACIONES sello EXAMEN · pág. 18 · art. 37","q":[{"i":"26-112","p":"Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. Promoción profesional. La totalidad de las plazas convocadas para el ingreso en la enseñanza de formación con la que se accede a la escala de suboficiales se reservará, en la modalidad de promoción interna, a los miembros de la escala de cabos y guardias, que lleven, al menos_____ de tiempo de servicios en dicha escala y cumplan, además, los requisitos establecidos en los artículos 33 y 34.","o":["2 años.","3 años.","4 años.","Ninguna es correcta."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">2 años</mark></span><span class=\"ref-norma\">Art. 37 · Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil</span><span class=\"ref-concepto\">\"que lleven, al menos, dos años de tiempo de servicios en dicha escala y cumplan, además, los requisitos establecidos en los artículos 33 y 34\"</span>"},{"i":"26-ia-1439","p":"Ley Orgánica 12/2007, de 22 de octubre, del régimen disciplinario de la Guardia Civil. Competencias de los Jefes de Unidades o Grupos Temporales. Tienen potestad para imponer sanciones al personal a sus órdenes los Jefes de Unidades o Grupos Temporales de la Guardia Civil, cualquiera que sea la denominación que reciban. El ejercicio de la potestad sancionadora, temporalmente circunscrita a la duración de la misión para la que fueron creadas dichas Unidades o Grupos, dependerá de:","o":["su entidad y de la antigüedad que tengan sus Jefes conforme a las reglas contenidas en los artículos anteriores.","su duración y del empleo que tengan sus Jefes conforme a las reglas contenidas en los artículos anteriores.","su entidad y del empleo que tengan sus Jefes conforme a las reglas contenidas en los artículos anteriores.","la autorización expresa del Director General de la Policía y de la Guardia Civil para cada misión."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">su entidad y del empleo que tengan sus Jefes conforme a las reglas contenidas en los artículos anteriores</mark></span><span class=\"ref-norma\">Art.  37 · Ley Orgánica 12/2007, de 22 de octubre, del régimen disciplinario de la Guardia Civil</span><span class=\"ref-concepto\">\"dependerá de su entidad y del empleo que tengan sus Jefes conforme a las reglas contenidas en los artículos anteriores\"</span>Depende de la entidad de la Unidad y del empleo del Jefe."}]},{"a":"Artículo 43 · Derechos y deberes R7","q":[{"i":"26-162","p":"Ley Orgánica 11/2007, de 22 de octubre, reguladora de los Derechos y Deberes de los miembros de la Guardia Civil. De las asociaciones profesionales. Asociaciones representativas. Serán consideradas asociaciones profesionales representativas las que hubieran obtenido en las elecciones al Consejo de Guardia Civil:","o":["Al menos, dos representantes","En una de las escalas, el cinco por ciento de los votos emitidos en cada una de ellas","Al menos, un representante","En dos de las escalas, el cinco por ciento de los votos emitidos en cada una de ellas"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Al menos, un representante</mark></span><span class=\"ref-norma\">Art. 43 · Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil</span><span class=\"ref-concepto\">\"Serán consideradas asociaciones profesionales representativas las que hubieran obtenido en las elecciones al Consejo de Guardia Civil, al menos, un representante o, en dos de las Escalas, el diez por ciento de los votos emitidos en cada una de ellas.\"</span>"},{"i":"26-212","p":"Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil. Asociaciones representativas. Serán consideradas asociaciones profesionales representativas las que hubieran obtenido en las elecciones al Consejo de Guardia Civil:","o":["Al menos, dos representantes o, en una de las Escalas, el diez por ciento de los votos emitidos en ella.","Al menos, un representante o, en las tres Escalas, el cinco por ciento de los votos emitidos en cada una de ellas.","Al menos, tres representantes o, en dos de las Escalas, el veinte por ciento de los votos emitidos en cada una de ellas.","Al menos, un representante o, en dos de las Escalas, el diez por ciento de los votos emitidos en cada una de ellas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Al menos, un representante o, en dos de las Escalas, el diez por ciento de los votos emitidos en cada una de ellas</mark></span><span class=\"ref-norma\">Art. 43 · Ley Orgánica 11/2007, reguladora de los derechos y deberes de los miembros de la Guardia Civil</span> <span class=\"ref-concepto\">\"Serán consideradas asociaciones profesionales representativas las que hubieran obtenido en las elecciones al Consejo de Guardia Civil, al menos, un representante o, en dos de las Escalas, el diez por ciento de los votos emitidos en cada una de ellas.\"</span>"},{"i":"26-ia-1127","p":"Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil. Asociaciones representativas. Serán consideradas asociaciones profesionales representativas las que hubieran obtenido en las elecciones al Consejo de Guardia Civil, al menos, un representante o, en dos de las Escalas:","o":["el cinco por ciento de los votos emitidos en cada una de ellas.","el diez por ciento de los votos emitidos en el conjunto de ellas.","el diez por ciento de los votos emitidos en cada una de ellas.","el quince por ciento de los votos emitidos en cada una de ellas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el diez por ciento de los votos emitidos en cada una de ellas</mark></span><span class=\"ref-norma\">Art.  43 · Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil</span><span class=\"ref-concepto\">\"o, en dos de las Escalas, el diez por ciento de los votos emitidos en cada una de ellas\"</span>Se exige el diez por ciento de los votos emitidos en cada una de las dos Escalas."},{"i":"26-ia-1128","p":"Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil. Asociaciones representativas. Serán consideradas asociaciones profesionales representativas las que hubieran obtenido en las elecciones al Consejo de Guardia Civil, al menos, __________ o, en __________ de las Escalas, el diez por ciento de los votos emitidos en cada una de ellas.","o":["dos representantes / una","un representante / dos","un representante / tres","un representante / todas"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">un representante / dos</mark></span><span class=\"ref-norma\">Art.  43 · Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil</span><span class=\"ref-concepto\">\"al menos, un representante o, en dos de las Escalas, el diez por ciento de los votos emitidos\"</span>Es un representante, o el diez por ciento en dos Escalas."}]},{"a":"CONSEJO DE LA GUARDIA CIVIL pág. 23 · art. 52 · R9","q":[{"i":"26-204","p":"Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. La carrera profesional en el Cuerpo de la Guardia Civil queda definida por:","o":["La progresiva capacitación para asumir puestos de mayor responsabilidad.","La ocupación de diferentes destinos.","El ascenso a los sucesivos empleos.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span><span class=\"ref-norma\">Art. 52 · Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil</span><span class=\"ref-concepto\">\"La carrera profesional en el Cuerpo de la Guardia Civil queda definida por el ascenso a los sucesivos empleos, la ocupación de diferentes destinos y la progresiva capacitación para asumir puestos de mayor responsabilidad, combinando formación y experiencia profesional en el desempeño de los cometidos del Cuerpo y en el ejercicio de las facultades de su escala.\"</span>"},{"i":"26-ia-1152","p":"Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil. Consejo de la Guardia Civil. Bajo la presidencia del Ministro del Interior, o persona en quien delegue, se crea el Consejo de la Guardia Civil como órgano colegiado en el que participarán representantes de los miembros del Cuerpo de la Guardia Civil y de:","o":["los Ministerios del Interior y de Defensa, con el fin de mejorar las condiciones profesionales y retributivas de sus integrantes, en los términos que se determinen reglamentariamente.","los Ministerios del Interior y de Defensa, con el fin de mejorar las condiciones profesionales de su integrantes, así como el funcionamiento del Instituto.","los Ministerios del Interior, de Defensa y de Hacienda, con el fin de mejorar las condiciones profesionales de sus integrantes.","las asociaciones profesionales y del Ministerio del Interior, con el fin de mejorar el funcionamiento del Instituto."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">los Ministerios del Interior y de Defensa, con el fin de mejorar las condiciones profesionales de su integrantes, así como el funcionamiento del Instituto</mark></span><span class=\"ref-norma\">Art.  52 · Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil</span><span class=\"ref-concepto\">\"participarán representantes de los miembros del Cuerpo de la Guardia Civil y de los Ministerios del Interior y de Defensa, con el fin de mejorar las condiciones profesionales de su integrantes, así como el funcionamiento del Instituto\"</span>Participan representantes de la Guardia Civil y de los Ministerios del Interior y de Defensa; el fin incluye el funcionamiento del Instituto."},{"i":"26-ia-1153","p":"Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil. Consejo de la Guardia Civil. El Consejo de la Guardia Civil se crea bajo la presidencia:","o":["del Ministro del Interior, o persona en quien delegue.","del Director General de la Guardia Civil, o persona en quien delegue.","del Ministro de Defensa, o persona en quien delegue.","del Secretario de Estado de Seguridad, o persona en quien delegue."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">del Ministro del Interior, o persona en quien delegue</mark></span><span class=\"ref-norma\">Art.  52 · Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil</span><span class=\"ref-concepto\">\"Bajo la presidencia del Ministro del Interior, o persona en quien delegue, se crea el Consejo de la Guardia Civil\"</span>Lo preside el Ministro del Interior o quien delegue."},{"i":"26-ia-1519","p":"Ley Orgánica 12/2007, de 22 de octubre, del régimen disciplinario de la Guardia Civil. Nombramiento de instructor y secretario. La autoridad que ordene la incoación del procedimiento por falta grave o muy grave designará:","o":["un instructor, a cuyo cargo correrá su tramitación, y un asesor jurídico que le asista.","un instructor y un secretario, a cuyo cargo correrá conjuntamente su tramitación.","un instructor, a cuyo cargo correrá su tramitación, y un secretario que le asista.","un instructor, a cuyo cargo correrá su resolución, y un secretario que le asista."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">un instructor, a cuyo cargo correrá su tramitación, y un secretario que le asista</mark></span><span class=\"ref-norma\">Art.  52.1 · Ley Orgánica 12/2007, de 22 de octubre, del régimen disciplinario de la Guardia Civil</span><span class=\"ref-concepto\">\"designará un instructor, a cuyo cargo correrá su tramitación, y un secretario que le asista\"</span>Instructor y secretario; el instructor tramita."},{"i":"26-ia-1520","p":"Ley Orgánica 12/2007, de 22 de octubre, del régimen disciplinario de la Guardia Civil. Nombramiento de instructor y secretario. El nombramiento de instructor, en el procedimiento por falta grave o muy grave, recaerá en:","o":["un Oficial General u Oficial destinado en la Guardia Civil de empleo superior y más antiguo que cualquiera de los infractores.","un Oficial General u Oficial destinado en la Guardia Civil de empleo superior o más antiguo que cualquiera de los infractores.","un Oficial General, Oficial o Suboficial destinado en la Guardia Civil de empleo superior o más antiguo que cualquiera de los infractores.","un Oficial destinado en la misma unidad que el infractor, de empleo superior o más antiguo que éste."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">un Oficial General u Oficial destinado en la Guardia Civil de empleo superior o más antiguo que cualquiera de los infractores</mark></span><span class=\"ref-norma\">Art.  52.2 · Ley Orgánica 12/2007, de 22 de octubre, del régimen disciplinario de la Guardia Civil</span><span class=\"ref-concepto\">\"El nombramiento de instructor recaerá en un Oficial General u Oficial destinado en la Guardia Civil de empleo superior o más antiguo que cualquiera de los infractores\"</span>Basta empleo superior o más antiguo; los Suboficiales no pueden ser instructores."},{"i":"26-ia-1521","p":"Ley Orgánica 12/2007, de 22 de octubre, del régimen disciplinario de la Guardia Civil. Nombramiento de instructor y secretario. Deberá notificarse al interesado:","o":["la incoación del procedimiento y el nombramiento de instructor y secretario.","la incoación del procedimiento y el nombramiento de instructor, pero no del secretario.","el nombramiento de instructor y secretario, una vez practicadas las primeras diligencias.","la incoación del procedimiento, el nombramiento de instructor y secretario y el pliego de cargos."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la incoación del procedimiento y el nombramiento de instructor y secretario</mark></span><span class=\"ref-norma\">Art.  52.3 · Ley Orgánica 12/2007, de 22 de octubre, del régimen disciplinario de la Guardia Civil</span><span class=\"ref-concepto\">\"Deberá notificarse al interesado la incoación del procedimiento y el nombramiento de instructor y secretario\"</span>Se notifica la incoación y el nombramiento de instructor y secretario."},{"i":"26-ia-2005","p":"Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. Carrera profesional. La carrera profesional en el Cuerpo de la Guardia Civil queda definida por el ascenso a los sucesivos empleos, la ocupación de diferentes destinos y:","o":["la progresiva capacitación para asumir puestos de mayor responsabilidad, combinando formación y experiencia profesional.","la progresiva capacitación para asumir puestos de mayor responsabilidad, combinando antigüedad y experiencia profesional en el Cuerpo.","la progresiva asignación de puestos de mayor responsabilidad, combinando formación y antigüedad en los distintos empleos.","la continua capacitación para asumir puestos de mayor responsabilidad, combinando mérito y experiencia profesional en el Cuerpo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la progresiva capacitación para asumir puestos de mayor responsabilidad, combinando formación y experiencia profesional</mark></span><span class=\"ref-norma\">Art.  52 · Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil</span><span class=\"ref-concepto\">\"la progresiva capacitación para asumir puestos de mayor responsabilidad, combinando formación y experiencia profesional\"</span>Combina formación y experiencia profesional."},{"i":"26-ia-2006","p":"Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. Carrera profesional. La carrera profesional se define combinando formación y __________ en el desempeño de los cometidos del Cuerpo y en el ejercicio de las facultades de su escala.","o":["antigüedad profesional, en los términos que se determinen reglamentariamente.","mérito profesional","experiencia docente","experiencia profesional"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">experiencia profesional</mark></span><span class=\"ref-norma\">Art.  52 · Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil</span><span class=\"ref-concepto\">\"combinando formación y experiencia profesional en el desempeño de los cometidos del Cuerpo y en el ejercicio de las facultades de su escala\"</span>Se combina formación con experiencia profesional."}]},{"a":"SESIONES DEL CONSEJO esquema con llave · pág. 25 · antes del art. 56","q":[{"i":"26-ia-1167","p":"Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil. Elección a miembros del Consejo. Serán electores los Guardias Civiles en situación de servicio activo o reserva. Serán elegibles:","o":["los que estuvieren en situación de servicio activo o reserva en la correspondiente Escala.","los que estuvieren en situación de servicio activo en cualquier Escala.","los que estuvieren en situación de servicio activo en la correspondiente Escala.","los que llevaren al menos cinco años de servicio en la correspondiente Escala."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">los que estuvieren en situación de servicio activo en la correspondiente Escala</mark></span><span class=\"ref-norma\">Art.  56.1 · Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil</span><span class=\"ref-concepto\">\"Serán elegibles los que estuvieren en situación de servicio activo en la correspondiente Escala\"</span>Son electores en activo o reserva, pero elegibles solo en servicio activo."},{"i":"26-ia-1168","p":"Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil. Elección a miembros del Consejo. Los candidatos a la elección se presentarán mediante listas de ámbito nacional para cada una de las Escalas, debiendo:","o":["pertenecer a la Escala o a la inmediatamente superior a la que se presenten.","pertenecer a la Escala a cuya elección se presenten.","estar avalados por el diez por ciento de los electores de la Escala.","pertenecer a una asociación profesional o agrupación de electores."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">pertenecer a la Escala a cuya elección se presenten</mark></span><span class=\"ref-norma\">Art.  56.2 · Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil</span><span class=\"ref-concepto\">\"listas de ámbito nacional para cada una de las Escalas, debiendo pertenecer a la Escala a cuya elección se presenten\"</span>Los candidatos deben pertenecer a la Escala por la que se presentan."},{"i":"26-ia-1169","p":"Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil. Elección a miembros del Consejo. Podrán presentar candidatos tanto las asociaciones profesionales legalmente constituidas como las agrupaciones de electores, siempre que la agrupación esté formada, al menos, por:","o":["el 10% de los efectivos incluidos en el censo electoral de la Escala a la que se presente la candidatura.","el 5% de los efectivos incluidos en el censo electoral de la Escala a la que se presente la candidatura.","el 10% de los efectivos incluidos en el censo electoral de todas las Escalas.","el 15% de los efectivos incluidos en el censo electoral de la Escala a la que se presente la candidatura, en los términos que se determinen reglamentariamente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el 10% de los efectivos incluidos en el censo electoral de la Escala a la que se presente la candidatura</mark></span><span class=\"ref-norma\">Art.  56.3 · Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil</span><span class=\"ref-concepto\">\"siempre que la agrupación esté formada, al menos, por el 10% de los efectivos incluidos en el censo electoral de la Escala a la que se presente la candidatura\"</span>Se exige el 10% del censo de la Escala correspondiente."},{"i":"26-ia-1170","p":"Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil. Elección a miembros del Consejo. En el caso de las agrupaciones de electores, los firmantes, cuya identificación deberá constar de manera fehaciente:","o":["podrán tener la condición de afiliados a alguna asociación profesional, pero no avalar a más de una candidatura.","no podrán tener la condición de afiliados a alguna asociación profesional, aunque sí avalar a varias candidaturas, salvo que la autoridad judicial disponga otra cosa.","no podrán ser representantes de asociaciones profesionales ni avalar a más de dos candidaturas.","no podrán tener la condición de afiliados a alguna asociación profesional del Cuerpo de la Guardia Civil, ni avalar a más de una candidatura."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">no podrán tener la condición de afiliados a alguna asociación profesional del Cuerpo de la Guardia Civil, ni avalar a más de una candidatura</mark></span><span class=\"ref-norma\">Art.  56.3 · Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil</span><span class=\"ref-concepto\">\"no podrán tener la condición de afiliados a alguna asociación profesional del Cuerpo de la Guardia Civil, ni avalar a más de una candidatura\"</span>Los firmantes no pueden ser afiliados ni avalar a más de una candidatura."},{"i":"26-ia-1171","p":"Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil. Elección a miembros del Consejo. Las listas de candidatos deberán contener tantos nombres como puestos a cubrir, más:","o":["la mitad de suplentes.","dos suplentes por cada Escala.","igual número de suplentes.","un suplente por cada puesto de más de una Escala."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">igual número de suplentes</mark></span><span class=\"ref-norma\">Art.  56.4 · Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil</span><span class=\"ref-concepto\">\"Las listas de candidatos deberán contener tantos nombres como puestos a cubrir, más igual número de suplentes\"</span>Se añade igual número de suplentes."},{"i":"26-ia-1172","p":"Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil. Elección a miembros del Consejo. Mediante el sistema de representación proporcional se atribuirá a cada lista el número de puestos que le correspondan, de conformidad con el cociente que resulte de dividir el número de votos válidos por el de puestos a cubrir. Los puestos sobrantes, en su caso, se atribuirán a las listas:","o":["en orden creciente, según el resto de votos de cada una de ellas.","en orden decreciente, según el resto de votos de cada una de ellas.","en orden decreciente, según el número total de votos de cada una de ellas.","a la lista que hubiera obtenido más votos válidos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">en orden decreciente, según el resto de votos de cada una de ellas</mark></span><span class=\"ref-norma\">Art.  56.5 · Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil</span><span class=\"ref-concepto\">\"Los puestos sobrantes, en su caso, se atribuirán a las listas, en orden decreciente, según el resto de votos de cada una de ellas\"</span>Los sobrantes se reparten en orden decreciente según el resto de votos."},{"i":"26-ia-1173","p":"Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil. Elección a miembros del Consejo. La inobservancia de cualquiera de las reglas del procedimiento de elección determinará la nulidad de la elección del candidato o candidatos afectados. La verificación del cumplimiento de dichos requisitos corresponderá:","o":["a la Dirección General de la Policía y la Guardia Civil.","a la Secretaría de Estado de Seguridad.","al Presidente del Consejo de la Guardia Civil.","a la Junta Electoral designada por el Ministro del Interior."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">a la Dirección General de la Policía y la Guardia Civil</mark></span><span class=\"ref-norma\">Art.  56.7 · Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil</span><span class=\"ref-concepto\">\"La verificación del cumplimiento de dichos requisitos corresponderá a la Dirección General de la Policía y la Guardia Civil\"</span>La verificación la hace la Dirección General de la Policía y la Guardia Civil."},{"i":"26-ia-1174","p":"Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil. Elección a miembros del Consejo. La duración del mandato de los representantes será de cuatro años, pudiendo ser reelegidos en sucesivos procesos electorales. Si en ese tiempo pasaran a situación administrativa diferente del servicio activo:","o":["conservarán la condición de representantes hasta el fin del mandato.","pasarán a ser suplentes de la lista a la que pertenecían.","perderán la condición de representantes, salvo que pasen a la reserva.","perderán la condición de representantes."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">perderán la condición de representantes</mark></span><span class=\"ref-norma\">Art.  56.8 · Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil</span><span class=\"ref-concepto\">\"Si en ese tiempo pasaran a situación administrativa diferente del servicio activo, perderán la condición de representantes\"</span>Pierden la condición de representantes."},{"i":"26-ia-1175","p":"Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil. Elección a miembros del Consejo. La duración del mandato de los representantes en el Consejo de la Guardia Civil será de __________ años, pudiendo ser reelegidos en sucesivos procesos electorales.","o":["tres","cinco, previo informe de la unidad policial competente.","cuatro","seis"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">cuatro</mark></span><span class=\"ref-norma\">Art.  56.8 · Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil</span><span class=\"ref-concepto\">\"La duración del mandato de los representantes será de cuatro años, pudiendo ser reelegidos en sucesivos procesos electorales\"</span>El mandato es de cuatro años, reelegible."},{"i":"26-ia-1526","p":"Ley Orgánica 12/2007, de 22 de octubre, del régimen disciplinario de la Guardia Civil. Tramitación. El instructor procederá a tomar declaración al inculpado, para lo cual le citará:","o":["a través de la autoridad que ordenó la incoación del expediente.","directamente, mediante notificación personal con cuarenta y ocho horas de antelación.","a través del secretario designado, en su domicilio declarado.","a través del Jefe de su Unidad de destino o encuadramiento."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">a través del Jefe de su Unidad de destino o encuadramiento</mark></span><span class=\"ref-norma\">Art.  56.1 · Ley Orgánica 12/2007, de 22 de octubre, del régimen disciplinario de la Guardia Civil</span><span class=\"ref-concepto\">\"para lo cual le citará a través del Jefe de su Unidad de destino o encuadramiento\"</span>La citación se hace por conducto del Jefe de su Unidad."},{"i":"26-ia-2017","p":"Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. Expediente académico. En el expediente académico constarán, entre otros, los títulos o estudios del Sistema Educativo Español, los declarados equivalentes u homologados por el Ministerio de __________ y aquellos títulos o certificados de estudios profesionales expedidos por los órganos competentes de las Administraciones Públicas.","o":["Educación, Cultura y Deporte","Defensa","Interior","Educación y Formación Profesional"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Educación, Cultura y Deporte</mark></span><span class=\"ref-norma\">Art.  56 · Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil</span><span class=\"ref-concepto\">\"los declarados equivalentes u homologados por el Ministerio de Educación, Cultura y Deporte y aquellos títulos o certificados de estudios profesionales expedidos por los órganos competentes de las Administraciones Públicas\"</span>La homologación la hace el Ministerio de Educación, Cultura y Deporte."}]},{"a":"DERECHOS DE LOS MIEMBROS DEL CONSEJO DE LA GUARDIA CIVIL diagrama de 4 cajas con flechas · pág. 26 · art. 57","q":[{"i":"26-ia-1176","p":"Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil. Derechos de los miembros del Consejo de la Guardia Civil. Los vocales del Consejo de la Guardia Civil, en representación de los miembros de la Institución, tendrán derecho a la libre circulación por las dependencias de su unidad electoral:","o":["sin necesidad de comunicación previa al jefe de la unidad.","sin que entorpezca el normal funcionamiento de las correspondientes unidades.","previa comunicación al jefe de la unidad electoral y sin entorpecer el servicio.","sin que entorpezca el normal funcionamiento de las unidades, salvo en zonas reservadas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">sin que entorpezca el normal funcionamiento de las correspondientes unidades</mark></span><span class=\"ref-norma\">Art.  57 · Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil</span><span class=\"ref-concepto\">\"Libre circulación por las dependencias de su unidad electoral, sin que entorpezca el normal funcionamiento de las correspondientes unidades\"</span>La libre circulación tiene como límite no entorpecer el funcionamiento de las unidades."},{"i":"26-ia-1177","p":"Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil. Derechos de los miembros del Consejo de la Guardia Civil. Entre los derechos de los vocales del Consejo de la Guardia Civil, en representación de los miembros de la Institución, se encuentra la acumulación en uno de los miembros de la candidatura de los créditos de tiempo, horas mensuales y permisos, previa comunicación:","o":["a la Dirección General de la Policía y de la Guardia Civil.","al jefe de la unidad, centro u órgano.","al Presidente del Consejo de la Guardia Civil, sin perjuicio de lo previsto en la normativa vigente.","a la Secretaría de Estado de Seguridad."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">a la Dirección General de la Policía y de la Guardia Civil</mark></span><span class=\"ref-norma\">Art.  57 · Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil</span><span class=\"ref-concepto\">\"Acumulación en uno de los miembros de la candidatura de los créditos de tiempo, horas mensuales y permisos, previa comunicación a la Dirección General de la Policía y de la Guardia Civil\"</span>La comunicación previa se dirige a la Dirección General de la Policía y de la Guardia Civil."},{"i":"26-ia-1178","p":"Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil. Derechos de los miembros del Consejo de la Guardia Civil. Señale la afirmación INCORRECTA sobre los derechos de los vocales del Consejo de la Guardia Civil elegidos en representación de los miembros de la Institución:","o":["Tienen derecho a la libre distribución de publicaciones referidas a cuestiones profesionales o asociativas.","Tienen derecho a la no discriminación en su promoción profesional en razón del desempeño de su representación.","Tienen derecho a la libre circulación por las dependencias de su unidad electoral.","Tienen derecho a que se les reduzca la jornada de servicio a la mitad durante todo su mandato."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Tienen derecho a que se les reduzca la jornada de servicio a la mitad durante todo su mandato</mark></span><span class=\"ref-norma\">Art.  57 · Ley Orgánica 11/2007, de 22 de octubre, reguladora de los derechos y deberes de los miembros de la Guardia Civil</span><span class=\"ref-concepto\">\"2. Libre distribución de publicaciones referidas a cuestiones profesionales o asociativas. 3. Acumulación en uno de los miembros de la candidatura de los créditos de tiempo\"</span>Los derechos son circulación, distribución de publicaciones, acumulación de créditos y no discriminación; no una reducción de jornada."}]},{"a":"Artículo 6 · Régimen disciplinario R12","q":[{"i":"26-71","p":"Ley Orgánica 12/2007 del régimen disciplinario de la Guardia Civil. Faltas disciplinarias. Las faltas disciplinarias pueden ser:","o":["Muy graves, graves y leves.","Menos graves, graves y leves.","Graves y leves.","Muy graves, menos graves y leves."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Muy graves, graves y leves</mark></span><span class=\"ref-norma\">Art. 6 · Ley Orgánica 12/2007, de 22 de octubre, del régimen disciplinario de la Guardia Civil</span><span class=\"ref-concepto\">\"Las faltas podrán ser muy graves, graves y leves.\"</span>"},{"i":"26-215","p":"Ley Orgánica 12/2007, de 22 de octubre, del régimen disciplinario de la Guardia Civil. Clases de faltas. Las faltas podrán ser:","o":["Muy graves, graves y leves.","Muy graves, graves, leves y levísimas, según su trascendencia para el servicio.","Graves, leves y de mera irregularidad, según la sanción que corresponda a cada una.","Muy graves y leves únicamente, según afecten o no al funcionamiento de la Institución."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Muy graves, graves y leves</mark></span><span class=\"ref-norma\">Art. 6 · Ley Orgánica 12/2007, del régimen disciplinario de la Guardia Civil</span> <span class=\"ref-concepto\">\"Las faltas podrán ser muy graves, graves y leves.\"</span>"},{"i":"26-ia-1253","p":"Ley Orgánica 12/2007, de 22 de octubre, del régimen disciplinario de la Guardia Civil. Clases de faltas. Las faltas podrán ser:","o":["muy graves, graves y leves.","muy graves, graves, leves y levísimas.","graves y leves, según su trascendencia.","muy graves y leves, según la sanción."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">muy graves, graves y leves</mark></span><span class=\"ref-norma\">Art.  6 · Ley Orgánica 12/2007, de 22 de octubre, del régimen disciplinario de la Guardia Civil</span><span class=\"ref-concepto\">\"Las faltas podrán ser muy graves, graves y leves\"</span>Hay tres clases: muy graves, graves y leves."}]},{"a":"Artículo 10 · Régimen disciplinario R13","q":[{"i":"26-ia-1342","p":"Ley Orgánica 12/2007, de 22 de octubre, del régimen disciplinario de la Guardia Civil. Finalidad de las sanciones. Las sanciones disciplinarias tienen por finalidad la corrección de comportamientos perjudiciales para el servicio o para los ciudadanos, o:","o":["lesivos para la imagen de la Institución.","lesivos para el funcionamiento de las Administraciones Públicas.","contrarios a la disciplina y al funcionamiento de la Institución.","lesivos para el funcionamiento de la Institución."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">lesivos para el funcionamiento de la Institución</mark></span><span class=\"ref-norma\">Art.  10 · Ley Orgánica 12/2007, de 22 de octubre, del régimen disciplinario de la Guardia Civil</span><span class=\"ref-concepto\">\"o lesivos para el funcionamiento de la Institución.\"</span>Los comportamientos son perjudiciales para el servicio o los ciudadanos, o lesivos para el funcionamiento de la Institución."},{"i":"26-216","p":"Ley Orgánica 12/2007, de 22 de octubre, del régimen disciplinario de la Guardia Civil. Finalidad de las sanciones. Las sanciones disciplinarias tienen por finalidad la corrección de comportamientos:","o":["Contrarios a la Constitución y al ordenamiento jurídico, o lesivos para la imagen de la Institución.","Perjudiciales para el servicio o para los compañeros, o lesivos para el prestigio del Cuerpo ante la sociedad.","Que supongan un incumplimiento de las órdenes recibidas, con independencia de su repercusión.","Perjudiciales para el servicio o para los ciudadanos, o lesivos para el funcionamiento de la Institución."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Perjudiciales para el servicio o para los ciudadanos, o lesivos para el funcionamiento de la Institución</mark></span><span class=\"ref-norma\">Art. 10 · Ley Orgánica 12/2007, del régimen disciplinario de la Guardia Civil</span> <span class=\"ref-concepto\">\"Las sanciones disciplinarias tienen por finalidad la corrección de comportamientos perjudiciales para el servicio o para los ciudadanos, o lesivos para el funcionamiento de la Institución.\"</span>"}]},{"a":"Artículo 28 · Régimen disciplinario R19","q":[{"i":"26-222","p":"Ley Orgánica 12/2007, de 22 de octubre, del régimen disciplinario de la Guardia Civil. Competencias del Director General de la Policía y de la Guardia Civil. Podrá imponer todas las sanciones, excepto la de separación del servicio:","o":["El Ministro del Interior, a propuesta del Director General de la Policía y de la Guardia Civil.","El Director General de la Policía y de la Guardia Civil.","El Director Adjunto Operativo de la Guardia Civil, previo informe del Consejo Asesor de Personal.","El Secretario de Estado de Seguridad, salvo las que correspondan a los oficiales generales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Director General de la Policía y de la Guardia Civil</mark></span><span class=\"ref-norma\">Art. 28 · Ley Orgánica 12/2007, del régimen disciplinario de la Guardia Civil</span> <span class=\"ref-concepto\">\"El Director General de la Policía y de la Guardia Civil podrá imponer todas las sanciones, excepto la de separación del servicio.\"</span>"}]},{"a":"Artículo 55 · Régimen disciplinario R23","q":[{"i":"26-226","p":"Ley Orgánica 12/2007, de 22 de octubre, del régimen disciplinario de la Guardia Civil. Plazos de instrucción. El procedimiento respetará los plazos establecidos, sin que la instrucción del expediente pueda exceder de:","o":["Tres meses, prorrogables por otros tres.","Seis meses.","Nueve meses, salvo que se declare su urgencia.","Un año, contado desde la notificación del acuerdo de incoación."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Seis meses</mark></span><span class=\"ref-norma\">Art. 55 · Ley Orgánica 12/2007, del régimen disciplinario de la Guardia Civil</span> <span class=\"ref-concepto\">\"sin que la instrucción del expediente pueda exceder de seis meses.\"</span>"},{"i":"26-ia-1525","p":"Ley Orgánica 12/2007, de 22 de octubre, del régimen disciplinario de la Guardia Civil. Plazos de instrucción. En el procedimiento por faltas graves y muy graves se respetarán los plazos establecidos, sin que la instrucción del expediente pueda exceder de:","o":["seis meses.","tres meses.","un año.","nueve meses."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">seis meses</mark></span><span class=\"ref-norma\">Art.  55 · Ley Orgánica 12/2007, de 22 de octubre, del régimen disciplinario de la Guardia Civil</span><span class=\"ref-concepto\">\"El procedimiento respetará los plazos establecidos, sin que la instrucción del expediente pueda exceder de seis meses\"</span>La instrucción no puede exceder de seis meses."}]},{"a":"MINISTRO DE DEFENSA · MINISTRO DE INTERIOR · CONJUNTAMENTE sello EXAMEN · pág. 84 · art. 9 · R28-R30","q":[{"i":"26-117","p":"Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. Competencias en materia de personal. Será competente para dirigir la política de personal relativa a los destinos y las retribuciones en la Guardia Civil:","o":["El Ministro del Interior.","El Ministro de Defensa.","El Secretario de Estado de Seguridad.","De forma conjunta el Ministro del Interior y el Ministro de Defensa."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Ministro del Interior</mark></span><span class=\"ref-norma\">Art. 9.b · Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil</span><span class=\"ref-concepto\">\"Corresponde al Ministro del Interior la dirección de la política de personal relativa a los destinos y las retribuciones.\"</span>"},{"i":"26-230","p":"Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. De los Ministros de Defensa y del Interior. Corresponde el ejercicio de la función directiva en lo concerniente al régimen de ascensos y situaciones administrativas del personal:","o":["Al Ministro del Interior, previo informe del Consejo de la Guardia Civil.","Al Ministro de Defensa.","Conjuntamente a los Ministros de Defensa y del Interior, en todo caso.","Al Director General de la Guardia Civil, por delegación del Ministro del Interior."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Al Ministro de Defensa</mark></span><span class=\"ref-norma\">Art. 9.a) · Ley 29/2014, de Régimen del Personal de la Guardia Civil</span> <span class=\"ref-concepto\">\"Corresponde al Ministro de Defensa el ejercicio de la función directiva en lo concerniente al régimen de ascensos y situaciones administrativas del personal.\"</span>"},{"i":"26-231","p":"Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. De los Ministros de Defensa y del Interior. Ejercerán sus competencias directivas en todo lo relacionado con la selección, la formación y el perfeccionamiento:","o":["Conjuntamente los Ministros de Defensa y del Interior.","El Ministro de Defensa, previo informe favorable del Ministro del Interior.","El Ministro del Interior, a propuesta del Director General de la Guardia Civil.","El Secretario de Estado de Seguridad y el Director General de la Guardia Civil, conjuntamente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Conjuntamente los Ministros de Defensa y del Interior</mark></span><span class=\"ref-norma\">Art. 9.c) · Ley 29/2014, de Régimen del Personal de la Guardia Civil</span> <span class=\"ref-concepto\">\"Conjuntamente ejercerán sus competencias directivas en todo lo relacionado con la selección, la formación y el perfeccionamiento.\"</span>"},{"i":"26-287","p":"Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. De los Ministros de Defensa y del Interior. Los Ministros de Defensa y del Interior dirigen la política de personal y de enseñanza en la Guardia Civil de acuerdo con la siguiente distribución de competencias:","o":["Según la naturaleza de la materia.","Según el empleo del personal afectado.","Según el ámbito territorial en que se preste el servicio.","Según la misión asignada en cada caso al Cuerpo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Según la naturaleza de la materia</mark></span><span class=\"ref-norma\">Art. 9 · Ley 29/2014, de Régimen del Personal de la Guardia Civil</span> <span class=\"ref-concepto\">\"Los Ministros de Defensa y del Interior dirigen la política de personal y de enseñanza en la Guardia Civil de acuerdo con la siguiente distribución de competencias según la naturaleza de la materia\"</span>"},{"i":"26-ia-1744","p":"Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. De los Ministros de Defensa y del Interior. Corresponde al Ministro de Defensa el ejercicio de la función directiva en lo concerniente:","o":["al régimen de ascensos y destinos del personal.","al régimen de ascensos y situaciones administrativas del personal.","al régimen de situaciones administrativas y retribuciones del personal.","al régimen de ascensos, situaciones administrativas y selección del personal."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">al régimen de ascensos y situaciones administrativas del personal</mark></span><span class=\"ref-norma\">Art.  9.a · Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil</span><span class=\"ref-concepto\">\"Corresponde al Ministro de Defensa el ejercicio de la función directiva en lo concerniente al régimen de ascensos y situaciones administrativas del personal\"</span>Defensa: ascensos y situaciones administrativas."},{"i":"26-ia-1745","p":"Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. De los Ministros de Defensa y del Interior. Corresponde al Ministro del Interior la dirección de la política de personal relativa a:","o":["los destinos y las retribuciones.","los destinos y las situaciones administrativas.","los ascensos y las retribuciones.","los destinos, las retribuciones y la formación."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">los destinos y las retribuciones</mark></span><span class=\"ref-norma\">Art.  9.b · Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil</span><span class=\"ref-concepto\">\"Corresponde al Ministro del Interior la dirección de la política de personal relativa a los destinos y las retribuciones\"</span>Interior: destinos y retribuciones."},{"i":"26-ia-1746","p":"Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. De los Ministros de Defensa y del Interior. Los Ministros de Defensa y del Interior ejercerán conjuntamente sus competencias directivas en todo lo relacionado con:","o":["la selección, la formación y los ascensos.","la selección, los destinos y el perfeccionamiento.","la formación, el perfeccionamiento y las retribuciones.","la selección, la formación y el perfeccionamiento."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la selección, la formación y el perfeccionamiento</mark></span><span class=\"ref-norma\">Art.  9.c · Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil</span><span class=\"ref-concepto\">\"Conjuntamente ejercerán sus competencias directivas en todo lo relacionado con la selección, la formación y el perfeccionamiento\"</span>Conjuntamente: selección, formación y perfeccionamiento."}]},{"a":"ACCIÓN DIRECTIVA · GESTIÓN · EJECUTIVA recuadro del apdo. 2 · pág. 87 · art. 15.2 · R32","q":[{"i":"26-13","p":"Texto: Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. Funciones. La ACCIÓN DE MANDO es ______ que se refiere al ejercicio de la autoridad y a la asunción de la consiguiente responsabilidad, y corresponde al guardia civil en razón de su cargo, destino o servicio.","o":["Una acción de gestión.","Una acción ejecutiva.","Una acción directiva.","Una acción ejecutiva y de gestión."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Una acción directiva</mark></span><span class=\"ref-norma\">Art. 15.3 · Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil</span><span class=\"ref-concepto\">\"La acción de mando es una acción directiva que se refiere al ejercicio de la autoridad y a la asunción de la consiguiente responsabilidad, y corresponde al guardia civil en razón de su cargo, destino o servicio\"</span>"},{"i":"26-37","p":"Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. Las acciones directivas de la Guardia Civil NO incluyen:","o":["Acción directiva.","Acción de gestión.","Acciones docentes.","Acción ejecutiva."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Acciones docentes</mark></span><span class=\"ref-norma\">Art. 15.1 · Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil</span><span class=\"ref-concepto\">\"Estas funciones se desarrollarán por medio de acciones directivas, que incluyen las de mando y de acciones de gestión y ejecutivas\"</span>Las funciones docentes son una clase de función, no una acción directiva."},{"i":"26-ia-1801","p":"Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. Funciones. Los guardias civiles realizarán funciones operativas, técnicas, logísticas, administrativas y docentes en el marco de la seguridad pública o de las misiones de carácter militar que se le puedan encomendar. Estas funciones se desarrollarán por medio de acciones directivas, que incluyen:","o":["las de mando y de acciones de gestión y ejecutivas.","las de mando, pero no las acciones de gestión ni las ejecutivas, que corresponden a otros niveles.","las de mando y las de coordinación, gestión y ejecutivas, según el cargo, destino o servicio.","las de mando y de acciones de gestión, pero no las ejecutivas, reservadas a la escala de cabos y guardias."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">las de mando y de acciones de gestión y ejecutivas</mark></span><span class=\"ref-norma\">Art.  15.1 · Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil</span><span class=\"ref-concepto\">\"Estas funciones se desarrollarán por medio de acciones directivas, que incluyen las de mando y de acciones de gestión y ejecutivas.\"</span>Las acciones directivas incluyen las de mando y las de gestión y ejecutivas; no se excluye ninguna."},{"i":"26-ia-1802","p":"Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. Funciones. La acción directiva se ejerce mediante la definición de __________ y la determinación de los medios para conseguirlos, estableciendo los planes correspondientes y controlando su ejecución.","o":["prioridades","funciones","misiones","objetivos"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">objetivos</mark></span><span class=\"ref-norma\">Art.  15.2 · Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil</span><span class=\"ref-concepto\">\"La acción directiva se ejerce mediante la definición de objetivos y la determinación de los medios para conseguirlos, estableciendo los planes correspondientes y controlando su ejecución.\"</span>Se definen objetivos y se determinan los medios para conseguirlos."},{"i":"26-ia-1803","p":"Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. Funciones. Mediante acciones de gestión se aplican los medios puestos a disposición para alcanzar los objetivos de la forma más __________.","o":["rápida","económica, en los términos que se determinen reglamentariamente.","eficiente","segura"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">eficiente</mark></span><span class=\"ref-norma\">Art.  15.2 · Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil</span><span class=\"ref-concepto\">\"Mediante acciones de gestión se aplican los medios puestos a disposición para alcanzar los objetivos de la forma más eficiente.\"</span>La forma más eficiente es el criterio de las acciones de gestión."},{"i":"26-ia-1804","p":"Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. Funciones. Por medio de acciones ejecutivas se ponen en práctica los planes establecidos actuando:","o":["en cumplimiento de órdenes concretas, pero nunca siguiendo procedimientos preestablecidos.","en cumplimiento de órdenes concretas o siguiendo procedimientos preestablecidos.","por iniciativa propia, de acuerdo con los objetivos definidos por la acción directiva.","siguiendo instrucciones generales y mediante la determinación de los medios necesarios."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">en cumplimiento de órdenes concretas o siguiendo procedimientos preestablecidos</mark></span><span class=\"ref-norma\">Art.  15.2 · Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil</span><span class=\"ref-concepto\">\"Por medio de acciones ejecutivas se ponen en práctica los planes establecidos actuando en cumplimiento de órdenes concretas o siguiendo procedimientos preestablecidos.\"</span>Las acciones ejecutivas actúan por órdenes concretas o por procedimientos preestablecidos, no por iniciativa propia."},{"i":"26-ia-1805","p":"Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. Funciones. Señale la afirmación INCORRECTA sobre la acción de mando:","o":["Es una acción de gestión que corresponde al guardia civil en razón de su cargo, destino o servicio.","Es una acción directiva que se refiere al ejercicio de la autoridad y a la asunción de la consiguiente responsabilidad.","Corresponde al guardia civil en razón de su cargo, destino o servicio, sin otro condicionante.","Para su ejercicio se podrá contar con la colaboración de los subordinados en tareas de información, planeamiento, asesoramiento, coordinación y control."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Es una acción de gestión que corresponde al guardia civil en razón de su cargo, destino o servicio</mark></span><span class=\"ref-norma\">Art.  15.3 · Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil</span><span class=\"ref-concepto\">\"La acción de mando es una acción directiva que se refiere al ejercicio de la autoridad y a la asunción de la consiguiente responsabilidad, y corresponde al guardia civil en razón de su cargo, destino o servicio.\"</span>La acción de mando es una acción directiva, no de gestión."},{"i":"26-ia-1806","p":"Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. Funciones. Para el ejercicio de la acción de mando se podrá contar con la colaboración de los subordinados en tareas de información, planeamiento, asesoramiento, coordinación y control, que constituyen:","o":["la acción de gestión.","el apoyo directivo.","la asistencia al mando.","el apoyo al mando."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el apoyo al mando</mark></span><span class=\"ref-norma\">Art.  15.3 · Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil</span><span class=\"ref-concepto\">\"coordinación y control, que constituyen el apoyo al mando.\"</span>Esas tareas constituyen el apoyo al mando."}]},{"a":"PRINCIPIOS DEL ASCENSO recuadro R46 · pág. 112 · art. 62.2","q":[{"i":"26-244","p":"Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. Normas generales. Los ascensos de los guardias civiles se producirán al empleo inmediato superior, con ocasión de vacante en la escala correspondiente, siempre que se reúnan las condiciones establecidas en esta Ley y de acuerdo con los principios de:","o":["Objetividad, igualdad de oportunidades, mérito y antigüedad en el empleo.","Legalidad, publicidad, igualdad de oportunidades, mérito y capacidad.","Objetividad, transparencia, jerarquía, disciplina y subordinación.","Objetividad, igualdad de oportunidades, mérito y capacidad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Objetividad, igualdad de oportunidades, mérito y capacidad</mark></span><span class=\"ref-norma\">Art. 62.2 · Ley 29/2014, de Régimen del Personal de la Guardia Civil</span> <span class=\"ref-concepto\">\"siempre que se reúnan las condiciones establecidas en esta Ley y de acuerdo con los principios de objetividad, igualdad de oportunidades, mérito y capacidad\"</span>"},{"i":"26-ia-1538","p":"Ley Orgánica 12/2007, de 22 de octubre, del régimen disciplinario de la Guardia Civil. Actuaciones complementarias. Recibido el expediente disciplinario, la autoridad competente, tras el examen de lo actuado, dictará resolución o lo devolverá al instructor para que:","o":["practique únicamente las diligencias complementarias propuestas por el interesado para resolver el procedimiento, salvo que la autoridad judicial disponga otra cosa.","formule nueva propuesta de resolución con calificación jurídica de menor gravedad que la inicial.","practique las diligencias omitidas, sin posibilidad de calificación jurídica de mayor gravedad.","practique las diligencias complementarias o las que hubieran sido omitidas que se consideren necesarias para resolver el procedimiento."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">practique las diligencias complementarias o las que hubieran sido omitidas que se consideren necesarias para resolver el procedimiento</mark></span><span class=\"ref-norma\">Art.  62.1 · Ley Orgánica 12/2007, de 22 de octubre, del régimen disciplinario de la Guardia Civil</span><span class=\"ref-concepto\">\"lo devolverá al instructor para que practique las diligencias complementarias o las que hubieran sido omitidas que se consideren necesarias para resolver el procedimiento\"</span>Puede devolverlo para diligencias complementarias u omitidas, o para propuesta con mayor gravedad."},{"i":"26-ia-2030","p":"Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. Normas generales. El régimen de ascensos tiene como finalidad asegurar que la Guardia Civil disponga, en los distintos empleos, de los profesionales con las competencias y experiencia adecuadas, para conseguir:","o":["su máxima eficacia, proporcionando oportunidades de ascenso y expectativas de progreso económico a sus miembros.","su máxima efectividad, garantizando oportunidades de ascenso y la estabilidad en el empleo de sus miembros.","su máxima efectividad, proporcionando oportunidades de destino y expectativas de progreso profesional a todos sus miembros.","su máxima efectividad, proporcionando oportunidades de ascenso y expectativas de progreso profesional a sus miembros."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">su máxima efectividad, proporcionando oportunidades de ascenso y expectativas de progreso profesional a sus miembros</mark></span><span class=\"ref-norma\">Art.  62.1 · Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil</span><span class=\"ref-concepto\">\"para conseguir su máxima efectividad, proporcionando oportunidades de ascenso y expectativas de progreso profesional a sus miembros\"</span>Busca máxima efectividad, con oportunidades de ascenso y expectativas de progreso profesional."},{"i":"26-ia-2031","p":"Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. Normas generales. Los ascensos de los guardias civiles se producirán al empleo inmediato superior, con ocasión de vacante en la escala correspondiente, siempre que se reúnan las condiciones establecidas en esta Ley y de acuerdo con los principios de:","o":["objetividad, igualdad de oportunidades, antigüedad y capacidad.","legalidad, igualdad de oportunidades, mérito y capacidad.","objetividad, igualdad de oportunidades, mérito y capacidad.","objetividad, publicidad, igualdad de oportunidades, mérito y capacidad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">objetividad, igualdad de oportunidades, mérito y capacidad</mark></span><span class=\"ref-norma\">Art.  62.2 · Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil</span><span class=\"ref-concepto\">\"de acuerdo con los principios de objetividad, igualdad de oportunidades, mérito y capacidad\"</span>Los principios son objetividad, igualdad de oportunidades, mérito y capacidad."},{"i":"26-ia-2032","p":"Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. Normas generales. Los ascensos de los guardias civiles se producirán al empleo inmediato superior, con ocasión de:","o":["vacante en la plantilla correspondiente, siempre que se reúnan las condiciones establecidas en esta Ley.","vacante en la escala correspondiente, siempre que se reúnan las condiciones establecidas en esta Ley.","vacante en el destino correspondiente, siempre que se reúnan las condiciones establecidas reglamentariamente.","vacante en la categoría correspondiente, siempre que se reúnan las condiciones establecidas en esta Ley."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">vacante en la escala correspondiente, siempre que se reúnan las condiciones establecidas en esta Ley</mark></span><span class=\"ref-norma\">Art.  62.2 · Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil</span><span class=\"ref-concepto\">\"con ocasión de vacante en la escala correspondiente, siempre que se reúnan las condiciones establecidas en esta Ley\"</span>La vacante es en la escala correspondiente."}]},{"a":"SISTEMAS DE ASCENSO recuadro R47 · pág. 112 · art. 63.1","q":[{"i":"26-73","p":"Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. Será sistema de ascenso:","o":["Antigüedad.","Concurso-oposición.","Elección.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span><span class=\"ref-norma\">Art. 63.1 · Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil</span><span class=\"ref-concepto\">\"Los sistemas de ascenso son los siguientes: a) Antigüedad. b) Concurso-oposición. c) Clasificación. d) Elección.\"</span>"},{"i":"26-245","p":"Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. Sistemas de ascenso. Los sistemas de ascenso son los siguientes:","o":["Antigüedad, concurso de méritos, clasificación y libre designación, según el empleo.","Antigüedad, oposición, clasificación, elección y cambio de escala, según el caso.","Antigüedad, concurso-oposición, clasificación y elección.","Concurso-oposición, clasificación, elección y libre designación, según el empleo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Antigüedad, concurso-oposición, clasificación y elección</mark></span><span class=\"ref-norma\">Art. 63.1 · Ley 29/2014, de Régimen del Personal de la Guardia Civil</span> <span class=\"ref-concepto\">\"Los sistemas de ascenso son los siguientes: a) Antigüedad. b) Concurso-oposición. c) Clasificación. d) Elección.\"</span>"},{"i":"26-297","p":"Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. Sistemas de ascenso. Los sistemas de ascenso son los siguientes:","o":["Antigüedad, concurso, méritos y elección.","Antigüedad, concurso-oposición, clasificación y libre designación.","Antigüedad, concurso-oposición, clasificación y elección.","Antigüedad, oposición, clasificación y elección."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Antigüedad, concurso-oposición, clasificación y elección</mark></span><span class=\"ref-norma\">Art. 63.1 · Ley 29/2014, de Régimen del Personal de la Guardia Civil</span> <span class=\"ref-concepto\">\"Los sistemas de ascenso son los siguientes\"</span> Son: a) Antigüedad; b) Concurso-oposición; c) Clasificación; d) Elección."},{"i":"26-ia-2033","p":"Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. Sistemas de ascenso. Señale la opción INCORRECTA. Son sistemas de ascenso:","o":["Concurso-oposición y evaluación.","Antigüedad y concurso-oposición, previo informe de la unidad policial competente.","Clasificación y elección.","Antigüedad y clasificación."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Concurso-oposición y evaluación</mark></span><span class=\"ref-norma\">Art.  63.1 · Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil</span><span class=\"ref-concepto\">\"Los sistemas de ascenso son los siguientes: a) Antigüedad. b) Concurso-oposición. c) Clasificación. d) Elección.\"</span>Los sistemas son antigüedad, concurso-oposición, clasificación y elección; no existe el de evaluación."},{"i":"26-ia-2034","p":"Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. Sistemas de ascenso. Los ascensos por el sistema de concurso-oposición se efectuarán según el orden resultante en el proceso selectivo y:","o":["en el correspondiente periodo de prácticas, según el procedimiento que se determine reglamentariamente, sin perjuicio de lo previsto en la normativa vigente.","en el correspondiente curso de capacitación, según el procedimiento que determine el Director General.","en el escalafón, según el procedimiento que se determine reglamentariamente.","en el correspondiente curso de capacitación, según el procedimiento que se determine reglamentariamente."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">en el correspondiente curso de capacitación, según el procedimiento que se determine reglamentariamente</mark></span><span class=\"ref-norma\">Art.  63.3 · Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil</span><span class=\"ref-concepto\">\"se efectuarán según el orden resultante en el proceso selectivo y en el correspondiente curso de capacitación, según el procedimiento que se determine reglamentariamente\"</span>Orden del proceso selectivo y del curso de capacitación."},{"i":"26-ia-2035","p":"Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. Sistemas de ascenso. En el sistema de ascenso por clasificación, el ascenso se producirá:","o":["por el orden resultante en el proceso selectivo.","por el orden de escalafón de los evaluados aptos.","por el orden derivado de un proceso de evaluación.","por elección entre los más capacitados del empleo inferior."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">por el orden derivado de un proceso de evaluación</mark></span><span class=\"ref-norma\">Art.  63.4 · Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil</span><span class=\"ref-concepto\">\"En el sistema por clasificación, el ascenso se producirá por el orden derivado de un proceso de evaluación\"</span>Por clasificación, el orden deriva de una evaluación."},{"i":"26-ia-2036","p":"Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. Sistemas de ascenso. El ascenso por el sistema de elección se concederá entre los del empleo inmediato inferior:","o":["con mayor antigüedad e idóneos para acceder al empleo superior.","más capacitados e idóneos para acceder al empleo superior.","más capacitados y con mayor tiempo de servicios en el empleo superior.","más idóneos, tras superar el correspondiente curso de capacitación."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">más capacitados e idóneos para acceder al empleo superior</mark></span><span class=\"ref-norma\">Art.  63.5 · Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil</span><span class=\"ref-concepto\">\"El ascenso por el sistema de elección se concederá entre los del empleo inmediato inferior más capacitados e idóneos para acceder al empleo superior\"</span>Se elige a los más capacitados e idóneos."}]},{"a":"SISTEMAS DE ASCENSO POR EMPLEOS esquema con llaves · pág. 113 · arts. 64-65","q":[{"i":"26-298","p":"Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. Ascenso a los diferentes empleos. Se efectuarán por el sistema de concurso-oposición los ascensos al empleo de:","o":["Cabo Primero.","Cabo.","Cabo Mayor.","Sargento."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Cabo</mark></span><span class=\"ref-norma\">Art. 64.2 · Ley 29/2014, de Régimen del Personal de la Guardia Civil</span> <span class=\"ref-concepto\">\"Se efectuarán por el sistema de concurso-oposición los ascensos al empleo de Cabo.\"</span>"},{"i":"26-ia-1539","p":"Ley Orgánica 12/2007, de 22 de octubre, del régimen disciplinario de la Guardia Civil. Disposiciones complementarias en la tramitación de determinados expedientes. En todos los expedientes disciplinarios instruidos por faltas graves o muy graves a miembros del Consejo de la Guardia Civil será preceptivo interesar la emisión de informe, no vinculante, de dicho Consejo, que se incorporará a las actuaciones. Dicho informe deberá ser emitido en el plazo de:","o":["cinco días.","quince días.","diez días.","un mes."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">diez días</mark></span><span class=\"ref-norma\">Art.  64.1 · Ley Orgánica 12/2007, de 22 de octubre, del régimen disciplinario de la Guardia Civil</span><span class=\"ref-concepto\">\"será preceptivo interesar la emisión de informe, no vinculante, de dicho Consejo, que se incorporará a las actuaciones. Dicho informe deberá ser emitido en el plazo de diez días\"</span>El informe, no vinculante, se emite en diez días."},{"i":"26-ia-1540","p":"Ley Orgánica 12/2007, de 22 de octubre, del régimen disciplinario de la Guardia Civil. Disposiciones complementarias en la tramitación de determinados expedientes. En el caso de expedientes instruidos por faltas muy graves se deberá oír al Consejo Superior de la Guardia Civil, cuya opinión se emitirá:","o":["una vez formulado por el instructor el pliego de cargos, incorporándose al procedimiento antes de que éste sea notificado al interesado.","una vez formulada por el instructor la correspondiente propuesta de resolución, incorporándose al procedimiento antes de que ésta sea notificada al interesado.","una vez formulada por el instructor la correspondiente propuesta de resolución, incorporándose al procedimiento después de que ésta sea notificada al interesado.","una vez dictada la resolución por la autoridad competente, incorporándose al procedimiento antes de su notificación al interesado."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">una vez formulada por el instructor la correspondiente propuesta de resolución, incorporándose al procedimiento antes de que ésta sea notificada al interesado</mark></span><span class=\"ref-norma\">Art.  64.2 · Ley Orgánica 12/2007, de 22 de octubre, del régimen disciplinario de la Guardia Civil</span><span class=\"ref-concepto\">\"cuya opinión se emitirá una vez formulada por el instructor la correspondiente propuesta de resolución, incorporándose al procedimiento antes de que ésta sea notificada al interesado\"</span>Se oye tras la propuesta de resolución y antes de notificarla."},{"i":"26-ia-2037","p":"Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. Ascenso a los diferentes empleos. Se efectuarán por el sistema de antigüedad los ascensos a los empleos de:","o":["Capitán, Sargento primero y Cabo primero.","Capitán, Sargento primero y Cabo mayor.","Teniente, Sargento primero y Cabo primero.","Capitán, Brigada, Sargento primero y Cabo primero."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Capitán, Sargento primero y Cabo primero</mark></span><span class=\"ref-norma\">Art.  64.1 · Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil</span><span class=\"ref-concepto\">\"Se efectuarán por el sistema de antigüedad los ascensos a los empleos de Capitán, Sargento primero y Cabo primero\"</span>Antigüedad: Capitán, Sargento primero y Cabo primero."},{"i":"26-ia-2038","p":"Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. Ascenso a los diferentes empleos. Se efectuarán por el sistema de concurso-oposición los ascensos al empleo de Cabo. El ascenso a este empleo otorgará la aptitud para el ascenso al de Cabo Primero:","o":["sin que en ningún caso pueda evaluarse dicha aptitud con posterioridad.","salvo que el interesado solicite expresamente ser evaluado de dicha aptitud, en los términos que se determinen reglamentariamente.","salvo que el Director General acuerde evaluar dicha aptitud en cada ciclo.","salvo que sobreviniera alguna circunstancia que aconsejara evaluar dicha aptitud."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">salvo que sobreviniera alguna circunstancia que aconsejara evaluar dicha aptitud</mark></span><span class=\"ref-norma\">Art.  64.2 · Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil</span><span class=\"ref-concepto\">\"El ascenso a este empleo otorgará la aptitud para el ascenso al de Cabo Primero, salvo que sobreviniera alguna circunstancia que aconsejara evaluar dicha aptitud\"</span>Otorga la aptitud salvo circunstancia sobrevenida que aconseje evaluarla."},{"i":"26-ia-2039","p":"Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. Ascenso a los diferentes empleos. Se efectuarán por el sistema de clasificación los ascensos a los empleos de:","o":["Teniente Coronel, Capitán, Subteniente y Brigada.","Coronel, Comandante, Subteniente y Brigada.","Teniente Coronel, Comandante, Subteniente y Brigada.","Teniente Coronel, Comandante, Suboficial mayor y Brigada."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Teniente Coronel, Comandante, Subteniente y Brigada</mark></span><span class=\"ref-norma\">Art.  64.3 · Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil</span><span class=\"ref-concepto\">\"Se efectuarán por el sistema de clasificación los ascensos a los empleos de Teniente Coronel, Comandante, Subteniente y Brigada\"</span>Clasificación: Teniente Coronel, Comandante, Subteniente y Brigada."},{"i":"26-ia-2040","p":"Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. Ascenso a los diferentes empleos. Se efectuarán por el sistema de elección los ascensos a los de la categoría de oficiales generales, a Coronel, Suboficial mayor, y:","o":["Teniente Coronel.","Cabo mayor.","Subteniente.","Cabo primero."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Cabo mayor</mark></span><span class=\"ref-norma\">Art.  64.4 · Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil</span><span class=\"ref-concepto\">\"Se efectuarán por el sistema de elección los ascensos a los de la categoría de oficiales generales, a Coronel, Suboficial mayor, y Cabo mayor\"</span>Elección: oficiales generales, Coronel, Suboficial mayor y Cabo mayor."}]},{"a":"EVALUACIÓN POR CLASIFICACIÓN: JUNTA → CONSEJO SUPERIOR → DIRECTOR GENERAL esquema impreso · pág. 115 · art. 68","q":[{"i":"26-ia-1549","p":"Ley Orgánica 12/2007, de 22 de octubre, del régimen disciplinario de la Guardia Civil. Concurrencia de sanciones. Cuando concurran varias sanciones y no sea posible su cumplimiento simultáneo, éste se llevará a cabo:","o":["por orden de mayor a menor gravedad.","por orden de menor a mayor gravedad.","por orden cronológico de imposición.","por orden de mayor a menor antigüedad de la infracción."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">por orden de mayor a menor gravedad</mark></span><span class=\"ref-norma\">Art.  68 · Ley Orgánica 12/2007, de 22 de octubre, del régimen disciplinario de la Guardia Civil</span><span class=\"ref-concepto\">\"éste se llevará a cabo por orden de mayor a menor gravedad\"</span>El cumplimiento sucesivo va de mayor a menor gravedad."},{"i":"26-ia-2056","p":"Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. Evaluaciones para el ascenso por clasificación. Serán evaluados para el ascenso por el sistema de clasificación, por la correspondiente junta de evaluación, quienes reúnan o puedan reunir, __________, las condiciones establecidas y se encuentren en las zonas de escalafón que para cada empleo y escala determine el Director General de la Guardia Civil.","o":["durante el ciclo de ascensos","antes del inicio del ciclo de ascensos","antes de que se produzca la vacante, previo informe de la unidad policial competente.","al finalizar el ciclo de ascensos"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">antes del inicio del ciclo de ascensos</mark></span><span class=\"ref-norma\">Art.  68.1 · Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil</span><span class=\"ref-concepto\">\"quienes reúnan o puedan reunir, antes del inicio del ciclo de ascensos, las condiciones establecidas\"</span>Se evalúa a quienes reúnan o puedan reunir las condiciones antes del inicio del ciclo."},{"i":"26-ia-2057","p":"Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. Evaluaciones para el ascenso por clasificación. En el ascenso por clasificación, el máximo y el mínimo de la relación entre el número de evaluados en cada ciclo y el de vacantes previstas se establecerá por orden del Ministro de Defensa:","o":["previo informe del Director General de la Guardia Civil.","a propuesta del Director General de la Guardia Civil.","previo informe del Consejo Superior de la Guardia Civil, sin perjuicio de lo previsto en la normativa vigente.","a propuesta del Ministro del Interior."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">previo informe del Director General de la Guardia Civil</mark></span><span class=\"ref-norma\">Art.  68.1 · Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil</span><span class=\"ref-concepto\">\"Por orden del Ministro de Defensa, previo informe del Director General de la Guardia Civil, se establecerá para cada período de vigencia de la plantilla\"</span>En clasificación, previo informe (no propuesta) del Director General."},{"i":"26-ia-2058","p":"Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. Evaluaciones para el ascenso por clasificación. Una vez informada la evaluación por clasificación por el Consejo Superior de la Guardia Civil, será elevada al Director General de la Guardia Civil, quién teniendo en cuenta, además, su propia valoración:","o":["declarará en primer término la aptitud o no aptitud de los evaluados para el ascenso y propondrá su orden de clasificación al Ministro de Defensa.","declarará la idoneidad de los evaluados para el ascenso y aprobará su orden de clasificación en primer término.","aprobará el orden de clasificación de los evaluados y declarará en último término su aptitud o no aptitud para el ascenso.","declarará en primer término la aptitud o no aptitud de los evaluados para el ascenso y aprobará su orden de clasificación."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">declarará en primer término la aptitud o no aptitud de los evaluados para el ascenso y aprobará su orden de clasificación</mark></span><span class=\"ref-norma\">Art.  68.2 · Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil</span><span class=\"ref-concepto\">\"quién teniendo en cuenta, además, su propia valoración, declarará en primer término la aptitud o no aptitud de los evaluados para el ascenso y aprobará su orden de clasificación\"</span>Declara aptitud en primer término y aprueba el orden de clasificación."}]},{"a":"CONCESIÓN DE LOS ASCENSOS pág. 118 · art. 73","q":[{"i":"26-ia-1557","p":"Ley Orgánica 12/2007, de 22 de octubre, del régimen disciplinario de la Guardia Civil. Requisitos generales de los recursos. Contra las resoluciones sancionadoras, los interesados podrán interponer, por escrito, los recursos de alzada y reposición en los términos previstos, sin perjuicio:","o":["del cumplimiento de las sanciones impuestas.","del plazo de prescripción de las sanciones impuestas.","de la suspensión de las sanciones impuestas.","de la anotación de las sanciones impuestas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">del cumplimiento de las sanciones impuestas</mark></span><span class=\"ref-norma\">Art.  73 · Ley Orgánica 12/2007, de 22 de octubre, del régimen disciplinario de la Guardia Civil</span><span class=\"ref-concepto\">\"los recursos de alzada y reposición en los términos previstos en los artículos siguientes, sin perjuicio del cumplimiento de las sanciones impuestas\"</span>Los recursos se presentan por escrito sin perjuicio del cumplimiento de la sanción."},{"i":"26-ia-2111","p":"Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. Concesión de los ascensos. Los ascensos a los empleos de la categoría de oficiales generales se concederán por:","o":["orden del Ministro de Defensa, a propuesta del Director General de la Guardia Civil, quien para efectuarla oirá al Consejo Superior.","real decreto acordado en Consejo de Ministros, a propuesta del Ministro del Interior, quien para efectuarla oirá al Ministro de Defensa, salvo que la autoridad judicial disponga otra cosa.","real decreto acordado en Consejo de Ministros, a propuesta del Ministro de Defensa, quien para efectuarla oirá al Ministro del Interior.","resolución del Director General de la Guardia Civil, previa propuesta del Consejo Superior, oyendo al Ministro del Interior."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">real decreto acordado en Consejo de Ministros, a propuesta del Ministro de Defensa, quien para efectuarla oirá al Ministro del Interior</mark></span><span class=\"ref-norma\">Art.  73.1 · Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil</span><span class=\"ref-concepto\">\"Los ascensos a los empleos de la categoría de oficiales generales se concederán por real decreto acordado en Consejo de Ministros, a propuesta del Ministro de Defensa, quien para efectuarla oirá al Ministro del Interior.\"</span>Real decreto, propuesta del Ministro de Defensa y audiencia al Ministro del Interior."},{"i":"26-ia-2112","p":"Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil. Concesión de los ascensos. La concesión del ascenso al empleo de Coronel, a Suboficial mayor y a Cabo mayor es competencia:","o":["del Director General de la Guardia Civil, previo informe del Consejo Superior.","del Ministro de Defensa, a propuesta del Director General de la Guardia Civil.","del Ministro del Interior, a propuesta del Director General de la Guardia Civil.","del Consejo de Ministros, a propuesta del Ministro de Defensa."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">del Ministro de Defensa, a propuesta del Director General de la Guardia Civil</mark></span><span class=\"ref-norma\">Art.  73.2 · Ley 29/2014, de 28 de noviembre, de Régimen del Personal de la Guardia Civil</span><span class=\"ref-concepto\">\"es competencia del Ministro de Defensa, a propuesta del Director General de la Guardia Civil\"</span>Compete al Ministro de Defensa a propuesta del Director General."}]},{"a":"QUINTO. Garantías · Protocolo violencia sobre la mujer","q":[{"i":"26-187","p":"Resolución de 6 de julio de 2021, de la Directora General, por la que se aprueba el Protocolo de actuación ante situaciones de violencia sobre la mujer que afecten a personal de la Guardia Civil. Bajo la guía de los principios rectores, las actuaciones que se lleven a cabo bajo el marco del protocolo asegurarán las siguientes garantías:","o":["Objetividad e imparcialidad en las actuaciones","Asistencia integral y especializada a las víctimas","Disponibilidad y acceso a mecanismos de prevención, protección, recuperación y actuación","Todas las anteriores"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas las anteriores</mark></span><span class=\"ref-norma\">Quinto.1 · Resolución de 6 de julio de 2021, del Director General de la Guardia Civil, por la que se aprueba el Protocolo de actuación ante situaciones de violencia sobre la mujer que afecten a personal de la Guardia Civil</span><span class=\"ref-concepto\">\"Bajo la guía de los principios rectores, las actuaciones que se lleven a cabo bajo el marco del protocolo asegurarán las condiciones siguientes: c) Objetividad e imparcialidad en las actuaciones. g) Asistencia integral y especializada a las víctimas. h) Disponibilidad y acceso a mecanismos de prevención, protección, recuperación y actuación\"</span>Esas tres son garantías del apartado Quinto, no los principios rectores del apartado Cuarto."},{"i":"26-ia-3024","p":"Resolución de 6 de julio de 2021, del Director General de la Guardia Civil, por la que se aprueba el Protocolo de actuación ante situaciones de violencia sobre la mujer que afecten a personal de la Guardia Civil. Garantías. Entre las condiciones que aseguran las actuaciones del protocolo figura la disponibilidad y acceso a:","o":["mecanismos de prevención, asistencia, recuperación y sanción.","mecanismos de prevención, protección, recuperación y actuación.","recursos de prevención, protección, recuperación y actuación.","mecanismos de detección, protección, recuperación y actuación, sin perjuicio de lo previsto en la normativa vigente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">mecanismos de prevención, protección, recuperación y actuación</mark></span><span class=\"ref-norma\">Quinto. 1 · Resolución de 6 de julio de 2021, del Director General de la Guardia Civil, por la que se aprueba el Protocolo de actuación ante situaciones de violencia sobre la mujer que afecten a personal de la Guardia Civil</span><span class=\"ref-concepto\">\"Disponibilidad y acceso a mecanismos de prevención, protección, recuperación y actuación.\"</span>Los mecanismos son de prevención, protección, recuperación y actuación."}]}];
